import java.util.*;
import java.io.*;

public class Main {

    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static PrintStream out = System.out;

    public static void main(String[] args) throws IOException {
        int[] inputs = readIntArray();
        int n = inputs[0];
        int m = inputs[1];
        out.println(app(n, m));
    }

    static int[] readIntArray() throws IOException {
        String line = br.readLine();
        String[] parts = line.trim().split("\\s+");
        int[] res = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            res[i] = Integer.parseInt(parts[i]);
        }
        return res;
    }

    static long[] tf(int n, int M) {
        long[] C = new long[n + 1];
        C[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            C[k] = (C[k + 1] * (k + 1)) % M;
            if (C[k] == 0)
                break;
        }
        return C;
    }

    static long app(int n, int M) {
        List<List<long[][]>> K = new ArrayList<>();
        List<long[][]> firstLayer = new ArrayList<>();
        firstLayer.add(new long[][]{{1}});
        K.add(firstLayer);
        for (int i = 0; i < n - 1; i++) {
            List<long[][]> prevLayer = K.get(i);
            int ni = prevLayer.size();
            long[][] Ki_ = new long[ni + i + 1][i + 2];
            for (int j = 0; j < ni; j++) {
                for (int k = 0; k < prevLayer.get(j)[0].length; k++) {
                    for (int h = 0; h <= i; h++) {
                        if (j + h < Ki_.length && k < Ki_[j + h].length) {
                            Ki_[j + h][k] += prevLayer.get(j)[0][k];
                            Ki_[j + h][k] %= M;
                        }
                    }
                }
                for (int k = 0; k < prevLayer.get(j)[0].length; k++) {
                    Ki_[j + i + 1][i + 1] += prevLayer.get(j)[0][k];
                    Ki_[j + i + 1][i + 1] %= M;
                }
            }
            List<long[][]> currentLayer = new ArrayList<>();
            for (long[] row : Ki_) {
                currentLayer.add(new long[][]{{row}});
            }
            K.add(currentLayer);
        }

        long[] C = tf(n, M);
        long s = 0;
        for (int i = 1; i < n; i++) {
            List<long[][]> KiLayer = K.get(i);
            int ni = KiLayer.size();
            int mi = (int) KiLayer.get(0)[0].length;
            long[][] Si = new long[ni][mi];
            for (int j = 0; j < ni; j++) {
                System.arraycopy(KiLayer.get(j)[0], 0, Si[j], 0, mi);
                for (int k = mi - 2; k >= 0; k--) {
                    Si[j][k] = (Si[j][k] + Si[j][k + 1]) % M;
                }
            }
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    Si[j][k] = (Si[j][k] + Si[j - 1][k]) % M;
                }
            }
            long si = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    si += (KiLayer.get(j)[0][k] * Si[j - 1][k + 1]) % M;
                    si %= M;
                }
            }
            long c = C[i + 1];
            si = (si * c) % M;
            s = (s + si) % M;
        }
        return s;
    }
}

